    // over the text regexes - `(() => void)[]` has @arr, so the `=>` in the
    // element type must not flip it to isFn. The text regexes cover
    // cfg.dtsPropsFor overrides with no hints.
    const hasFn = t.includes('/* @fn */'), hasArr = t.includes('/* @arr */');
