      // common {id|key} + {label|text|name|title} + value conventions.
      props[prop] = isList
        ? elIsString
          ? ['Item 1', 'Item 2', 'Item 3']
          : [1, 2, 3].map((i) => {
            const s = String(i), l = `Item ${i}`;
            return { id: s, key: s, value: s, label: l, text: l, name: l, title: l };
