    else if (/^string\b/.test(t)) props[prop] = name;
    else if (/^number\b/.test(t)) props[prop] = 0;
    else if (/^boolean\b/.test(t)) props[prop] = false;
    else if (/^\{/.test(t) || /Record<|Partial<|Pick<|Omit</.test(t)) props[prop] = {};
